  async function handleAuthSubmit() {
    if (authSubmitting) return;
    const email = String(authEmailInput || "").trim();
    const password = String(authPasswordInput || "");
    const passwordConfirm = String(authPasswordConfirmInput || "");
    const nickname = String(authNicknameInput || "").trim();
    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email || !password) {
      setAccountPanelError("이메일과 비밀번호를 입력해 주세요.");
      return;
    }
    if (!emailPattern.test(email)) {
      setAccountPanelError("이메일 형식이 올바르지 않습니다.");
      return;
    }
    if (password.length < 8) {
      setAccountPanelError("비밀번호는 8자 이상 입력해 주세요.");
      return;
    }
    if (authFormMode === "signup" && password !== passwordConfirm) {
      setAccountPanelError("비밀번호 확인이 일치하지 않습니다.");
      return;
    }
    if (authFormMode === "signup" && !nickname) {
      setAccountPanelError("닉네임을 입력해 주세요.");
      return;
    }
    if (authFormMode === "signup" && !authEmailVerified) {
      setAccountPanelError("이메일 인증을 먼저 완료해 주세요.");
      return;
    }
    if (authFormMode === "signup" && !authVerificationToken) {
      setAccountPanelError("인증정보가 만료되었습니다. 인증번호를 다시 확인해 주세요.");
      return;
    }
    if (authFormMode === "signup" && (!agreeTerms || !agreePrivacy || !agreeCollection)) {
      setAccountPanelError("필수 약관/개인정보 동의가 필요합니다.");
      return;
    }
    try {
      setAuthSubmitting(true);
      setAccountPanelError("");
      setAccountPanelInfo("");
      const payload = authFormMode === "signup" ? await signupAccount({
        email,
        password,
        verificationToken: authVerificationToken,
        nickname,
        agreeTerms,
        agreePrivacy,
        agreeCollection
      }) : await loginAccount({ email, password });
      const token = String(payload?.token || "");
      const user = payload?.user || {};
      if (!token) {
        throw new Error("로그인 세션이 발급되지 않았습니다.");
      }
      setAuthToken(token);
      setAccountProfile({
        name: String(user.nickname || ""),
        email: String(user.email || "")
      });
      setIsLoggedIn(true);
      setAccountPanelOpen(false);
      setAccountMenuOpen(false);
    } catch (error) {
      const message = toUiErrorMessage(
        error,
        authFormMode === "signup" ? "회원가입에 실패했습니다." : "로그인에 실패했습니다."
      );
      console.error("[auth][submit][error]", {
        mode: authFormMode,
        email,
        message,
        rawError: error
      });
      if (authFormMode === "signup" && message.includes("이미 가입된 이메일")) {
        setAuthFormMode("login");
        setAccountPanelInfo("이미 가입된 이메일입니다. 로그인으로 진행해 주세요.");
        setAccountPanelError("");
      } else {
        setAccountPanelError(message);
      }
    } finally {
      setAuthSubmitting(false);
    }
  }
